declare(strict_types=1);
function sexogateHomeIcon(string $name):string{
 $paths=['arrow'=>'M4 12h15m-6-6 6 6-6 6','heart'=>'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z','cart'=>'M2 3h3l3 13h11l3-10H6m3 15h.01M18 21h.01','compare'=>'M5 3v18M12 3v18M19 3v18M2 8h6m1 8h6m1-6h6','bookmark'=>'M6 3h12v18l-6-4-6 4Z'];
 return '<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="'.$paths[$name].'"/></svg>';
}
function sexogateHomeCard(array $product,array $catalog,string $locale,array $labels):string{
 $escape='nodenoSeoEscape';$id=$escape($product['id']);$name=$escape(nodenoSeoName($product,$locale));$link=$escape(nodenoSeoLink('product',$locale,['product'=>$product['id']]));
 $card='<article class="product-card"><div class="product-card-stage"><a class="product-stage" href="'.$link.'" data-product="'.$id.'">'.nodenoSeoPhoto($product,$catalog,$locale).'</a><button class="product-save" type="button" data-save="'.$id.'" aria-label="'.$escape($labels['favorites']).': '.$name.'" aria-pressed="false">'.sexogateHomeIcon('heart').'</button></div>';
 $card.='<div class="product-info"><h3><a href="'.$link.'" data-product="'.$id.'">'.$name.'</a></h3><p class="card-color">'.$escape(nodenoSeoLocal($product['variantColor']??[],$locale)).'</p><p class="pricing-note card-price-compact"><span class="card-price-main"><bdi class="product-price" data-price="'.$id.'" dir="auto">'.nodenoSeoPrice($product,$locale).'</bdi></span></p>';
 $card.='<button type="button" class="button card-add" data-add="'.$id.'">'.sexogateHomeIcon('cart').'<span>'.$escape($labels['add']).'</span></button><div class="card-tools"><button type="button" class="card-compare" data-compare="'.$id.'" aria-pressed="false">'.sexogateHomeIcon('compare').'<span>'.$escape($labels['compare']).'</span></button><button type="button" class="icon-button" data-collect="'.$id.'" aria-label="'.$escape($labels['addCollection']).': '.$name.'">'.sexogateHomeIcon('bookmark').'</button></div></div></article>';
 return $card;
}
function sexogateHomeShelf(array $products,array $catalog,string $locale,array $ui,string $title,string $kind,array $params=[]):string{
 if(!$products)return '';$e='nodenoSeoEscape';$cards='';foreach($products as $p)$cards.=sexogateHomeCard($p,$catalog,$locale,$ui);
 return '<section class="product-shelf sg-product-shelf sg-home-shelf sg-home-'.$kind.'" data-home-shelf="'.$kind.'"><div class="section-heading"><h2>'.$e($title).'</h2><a class="text-link" href="'.$e(nodenoSeoLink('catalog',$locale,$params)).'" data-nav>'.$e($ui['allProducts']).sexogateHomeIcon('arrow').'</a></div><div class="product-row sg-product-rail" tabindex="0" role="region" aria-label="'.$e($title).'">'.$cards.'</div></section>';
}
function sexogateStorefrontHome(array $catalog,array $config,string $locale,array $query=[]):string{
 require_once __DIR__.'/sexogate-home-model.php';$e='nodenoSeoEscape';$ui=json_decode((string)file_get_contents(__DIR__.'/sexogate-storefront-ui-copy.json'),true,32,JSON_THROW_ON_ERROR)[$locale];$c=json_decode((string)file_get_contents(__DIR__.'/sexogate-home-copy.json'),true,32,JSON_THROW_ON_ERROR)[$locale];$brand=json_decode((string)file_get_contents(__DIR__.'/sexogate-store-copy.json'),true,32,JSON_THROW_ON_ERROR)[$locale];
 $m=sexogateHomeModel($catalog,['category'=>is_string($query['homeCategory']??null)?$query['homeCategory']:'','featuredId'=>!empty($config['appearance']['enabled'])?($config['appearance']['heroProductId']??''):'']);$name=static fn($v)=>$e(nodenoSeoLocal($v['name'],$locale));$arrow=sexogateHomeIcon('arrow');$shortcuts='';
 foreach($m['shortcuts']as $v){$p=sexogateHomeMembers($m['products'],$catalog['categories'],$v['id'])[0];$shortcuts.='<a href="'.$e(nodenoSeoLink('catalog',$locale,['category'=>$v['id']])).'" data-nav data-home-shortcut="'.$e($v['id']).'"><span>'.nodenoSeoPhoto($p,$catalog,$locale,false).'</span><strong>'.$name($v).'</strong></a>';}
 $cards='';foreach($m['campaigns']as $entry){$category=$entry['category'];$p=$entry['product'];$cards.='<a class="sg-campaign-card" href="'.$e(nodenoSeoLink($category?'catalog':'product',$locale,$category?['category'=>$category['id']]:['product'=>$p['id']])).'" '.($category?'data-nav':'data-product="'.$e($p['id']).'"').'><span class="sg-campaign-image">'.nodenoSeoPhoto($p,$catalog,$locale,false).'</span><span class="sg-campaign-caption"><strong>'.($category?$name($category):$e(nodenoSeoName($p,$locale))).'</strong>'.$arrow.'</span></a>';}
 $title=!empty($config['appearance']['enabled'])&&trim((string)($config['appearance']['heroTitle_'.$locale]??''))!==''?$config['appearance']['heroTitle_'.$locale]:$brand['slogan'];$body='<div class="wrap home-page sg-home sg-market-home sg-home-page"><nav class="sg-home-shortcuts" aria-label="'.$e($c['categories']).'">'.$shortcuts.'</nav><div class="sg-home-heading"><h1 tabindex="-1">'.$e($title).'</h1><a class="text-link" href="'.$e(nodenoSeoLink('categories',$locale)).'" data-nav>'.$e($c['categories']).$arrow.'</a></div>';
 $body.=sexogateHomeShelf($m['selection'],$catalog,$locale,$ui,$c['selection'],'selection').'<section class="sg-home-campaigns" aria-label="'.$e($c['collections']).'"><div class="section-heading"><h2>'.$e($c['collections']).'</h2></div><div class="sg-campaign-grid">'.$cards.'</div></section>';
 if($m['lingerie'])$body.=sexogateHomeShelf($m['lingerieProducts'],$catalog,$locale,$ui,nodenoSeoLocal($m['lingerie']['name'],$locale),'lingerie',['category'=>$m['lingerie']['id']]);
 $selected=$m['selected']['id']??'';$tabs='';foreach([['id'=>'','name'=>[$locale=>$c['all']]],...$m['roots']]as $v){$id=$v['id'];$tabs.='<button type="button" role="tab" id="sg-home-tab-'.$e($id?:'all').'" aria-controls="sg-home-results" aria-selected="'.($selected===$id?'true':'false').'" tabindex="'.($selected===$id?'0':'-1').'" data-home-category="'.$e($id).'">'.$name($v).'</button>';}
 $items='';foreach($m['discovery']as $p)$items.=sexogateHomeCard($p,$catalog,$locale,$ui);$body.='<section id="sg-home-discovery" class="product-shelf sg-home-discovery" data-selected-category="'.$e($selected).'"><div class="section-heading"><h2>'.$e($c['discover']).'</h2><a class="text-link" href="'.$e(nodenoSeoLink('catalog',$locale,['category'=>$selected])).'" data-nav>'.$e($ui['allProducts']).$arrow.'</a></div><div class="sg-home-tabs" role="tablist" aria-label="'.$e($c['discover']).'">'.$tabs.'</div><div id="sg-home-results" role="tabpanel" aria-labelledby="sg-home-tab-'.$e($selected?:'all').'" tabindex="0"><div class="product-row sg-product-rail" tabindex="0" role="region" aria-label="'.$e($c['discover']).'">'.$items.'</div></div></section>';
 $blog=explode('?',nodenoSeoLink('home',$locale))[0].'blog?lang='.rawurlencode($locale);$body.='<section class="sg-home-guides"><div><span>SEXOGATE</span><h2>'.$e($c['guide']).'</h2><p>'.$e($c['guideBody']).'</p><a href="'.$e($blog).'" data-home-blog>'.$e($c['guideAction']).$arrow.'</a></div><nav aria-label="'.$e($c['help']).'"><a href="'.$e(nodenoSeoLink('help',$locale)).'" data-nav>'.$e($c['help']).$arrow.'</a><a href="mailto:info@sexogate.com">'.$e($c['contact']).$arrow.'</a></nav></section>';
 return $body.'</div>';
}
